import { PASSWORD, expect, expectStatus, test, uniqueName } from "../../fixtures";

// Assumption: the seed provides a Globex Procurement member. Override the email with
// GLOBEX_MEMBER_EMAIL if the seed uses a different address.
const GLOBEX_MEMBER_EMAIL = process.env.GLOBEX_MEMBER_EMAIL ?? "member@globex.test";

test.describe("vendor tenant isolation", () => {
  test(
    "vendors from another tenant are invisible",
    { tag: "@VEN-07" },
    async ({ apiAs, request }) => {
      // Arrange: a vendor owned by the Globex Procurement tenant
      const loginResponse = await request.post("/api/auth/login", {
        data: { email: GLOBEX_MEMBER_EMAIL, password: PASSWORD },
      });
      const globexToken = (await expectStatus<{ access_token: string }>(loginResponse, 200)).access_token;

      const globexClient = await request.newContext({
        baseURL: request.baseURL,
        extraHTTPHeaders: { Authorization: `Bearer ${globexToken}` },
      });
      let vendorId: string;
      try {
        const created = await globexClient.post("/api/vendors", {
          data: {
            name: uniqueName("Globex Vendor"),
            category: "software",
            contact_email: `${uniqueName("globex-contact").replace(/\s+/g, "-").toLowerCase()}@globex.test`,
          },
        });
        const vendor = await expectStatus<{ id: string }>(created, 201);
        vendorId = vendor.id;
      } finally {
        await globexClient.dispose();
      }

      // Act: a Northwind member requests the Globex vendor by id
      const member = await apiAs("member");
      const response = await member.get(`/api/vendors/${vendorId}`);

      // Assert
      const body = await expectStatus(response, 404);
      expect(body.error.code).toBe("vendor_not_found");
    },
  );
});
